namespace spark {
namespace {
constexpr const char* management_html=R"HTML(<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SPARK · Google login</title><style>body{background:#101820;color:#e5edf3;font:16px system-ui;max-width:780px;margin:40px auto;padding:20px}a{color:#78dfcc}button{font:inherit;padding:12px;margin:12px 8px 12px 0;cursor:pointer}pre{white-space:pre-wrap;overflow-wrap:anywhere}#error{color:#ffb5ad}</style><a href="/">Dashboard</a><h1>Google login</h1><p>Enrol your own Google account to sign in without entering an administrator token. Keep a recovery administrator token stored securely.</p><p id="status">Loading…</p><pre id="owner"></pre><label><input id="remember" type="checkbox">Remember this device after enrolment</label><div><button id="enrol" hidden>Enrol my Google account</button><button id="revoke" hidden>Sign out all Google sessions</button><button id="unlink" hidden>Unlink Google account</button></div><p id="error" role="alert"></p><script src="/auth/client.js"></script><script>
const el=id=>document.getElementById(id);let busy=false;
async function request(path,method='GET',body){const r=await fetch(path,{method,headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});const p=r.status===204?{}:await r.json();if(!r.ok)throw Error((p.error||'Request failed').replaceAll('_',' '));return p;}
async function load(){try{const s=await request('/admin/google');el('status').textContent=s.configured?(s.enrolled?'Your Google account is enrolled.':'Google is configured. Enrol your account to enable login.'):'Google login is not configured on this instance.';el('owner').textContent=s.owner?JSON.stringify({email:s.owner.email,permissions:s.owner.permissions},null,2):'';el('enrol').hidden=!s.configured||s.enrolled;el('revoke').hidden=el('unlink').hidden=!s.enrolled;}catch(e){el('error').textContent=e.message;}}
async function action(fn){if(busy)return;busy=true;for(const b of document.querySelectorAll('button'))b.disabled=true;el('error').textContent='';try{await fn();}catch(e){el('error').textContent=e.message;}finally{busy=false;for(const b of document.querySelectorAll('button'))b.disabled=false;}}
el('enrol').onclick=()=>action(async()=>{const p=await request('/admin/google/enroll','POST',{remember_device:el('remember').checked});location.assign(p.authorization_url);});
el('revoke').onclick=()=>{if(confirm('Sign out every Google session, including this one if you used Google?'))action(async()=>{await request('/admin/google/sessions/revoke','POST',{});location.assign('/login');});};
el('unlink').onclick=()=>{if(confirm('Unlink this Google account and revoke its sessions? You will need an administrator token to enrol an account again.'))action(async()=>{await request('/admin/google/owner','DELETE');location.assign('/login');});};load();
</script></html>)HTML";
}
void configure_google_auth(httplib::Server& server,std::shared_ptr<Authorization> auth){
 server.Get("/auth/google/options",[auth](const auto&,auto& res){try{auto google=auth?auth->google():nullptr;reply(res,200,{{"enabled",google&&google->status()["enrolled"]==true}});}catch(...){reply(res,200,{{"enabled",false}});}});
 body_route(server,"POST","/auth/google/start",[auth](const auto& req,auto& res){if(auth&&auth->google())auth->google()->start(req,res);else reply(res,503,{{"error","google_login_not_configured"}});});
 server.Get("/auth/google/callback",[auth](const auto& req,auto& res){if(auth&&auth->google())auth->google()->callback(req,res);else reply(res,503,{{"error","google_login_not_configured"}});});
 auto admin=[auth](const httplib::Request& req,httplib::Response& res){try{need(bool(auth),409,"authentication_disabled");auto who=auth->identity(req,res);if(!who)return;need(who->kind=="administrator"&&permitted(*who,"admin.credentials"),403,"administrator_required");need(req.params.empty(),400,"invalid_parameters");
 if(req.path=="/admin/google/explorer"){res.set_content(management_html,"text/html; charset=utf-8");return;}auto google=auth->google();if(req.path=="/admin/google"){reply(res,200,google?google->status():json{{"configured",false},{"enrolled",false},{"owner",nullptr}});return;}need(bool(google),503,"google_login_not_configured");
 if(req.path=="/admin/google/enroll"){google->start(req,res,*who);return;}
 if(req.method=="DELETE")need(req.body.empty(),400,"unexpected_body");else {auto packet=json::parse(req.body,nullptr,false);need(packet.is_object()&&packet.empty(),400,"invalid_packet");}google->reset(req.method=="DELETE");res.status=204;log_event("info","auth.google",req.method=="DELETE"?"Google owner unlinked":"Google sessions revoked");
 }catch(const Error& e){reply(res,e.status,{{"error",e.what()}});}catch(...){reply(res,503,{{"error","google_login_unavailable"}});}};
 server.Get("/admin/google",admin);server.Get("/admin/google/explorer",admin);body_route(server,"POST","/admin/google/enroll",admin,auth);body_route(server,"POST","/admin/google/sessions/revoke",admin,auth);body_route(server,"DELETE","/admin/google/owner",admin,auth);
}
json google_endpoints(){json out=json::array();for(const auto& e:std::vector<std::vector<std::string>>{
 {"GET","/auth/google/options","public","Reports whether Google login is configured and an owner is enrolled. No account details are returned."},
 {"POST","/auth/google/start","public","Start owner Google sign-in. Exact configured Host/Origin, X-SPARK-Login: 1 and JSON body required. Optional remember_device boolean. Returns authorization_url and sets a temporary Secure HttpOnly SameSite=Lax browser-binding cookie. Navigate the browser to authorization_url; flow expires in ten minutes."},
 {"GET","/auth/google/callback","public","Google authorization-code callback. Requires the one-time state and matching browser-binding cookie. Validates PKCE exchange, nonce, Google signature, issuer, audience, expiry and approved subject. Creates a SPARK session, never exposes Google tokens to the browser. Errors require a new login flow."},
 {"GET","/admin/google","protected","Read Google login configuration/enrolled owner and explicit permissions. Administrator with admin.credentials required."},
 {"GET","/admin/google/explorer","protected","Google owner enrolment and session-revocation management page."},
 {"POST","/admin/google/enroll","protected","Enrol the first Google owner from a currently valid administrator browser session with admin.credentials. Requires Origin and session CSRF. Returns authorization_url; initiating session must still be valid at callback. Enrolment captures that administrator's explicit permissions. Existing owner must be unlinked before enrolling another."},
 {"POST","/admin/google/sessions/revoke","protected","Revoke all Google sessions and pending Google flows by rotating the owner generation. Existing token credentials and their sessions remain valid."},
 {"DELETE","/admin/google/owner","protected","Unlink the approved Google account, revoke its sessions and invalidate pending flows. Recovery administrator token login is required to enrol again."}}){bool start=e[1]=="/auth/google/start"||e[1]=="/admin/google/enroll";json item={{"method",e[0]},{"path",e[1]},{"description",e[3]},{"input",{{"body",e[0]=="POST"?(start?json{{"remember_device",false}}:json::object()):json(nullptr)},{"headers",e[0]=="POST"?json{{"Content-Type","application/json"}}:json::object()}}},{"output",{{"status",e[0]=="DELETE"||e[1]=="/admin/google/sessions/revoke"?204:200},{"body",start?json{{"authorization_url","https://accounts.google.com/o/oauth2/v2/auth?..."}}:json("HTML, status object, or no content as described")}}},{"errors",{{"400","invalid_packet, invalid_google_state, google_login_cancelled"},{"401","invalid_google_token, expired_google_token"},{"403","browser_origin_mismatch, csrf_failed, google_account_not_allowed, administrator_session_required"},{"409","google_owner_not_enrolled, google_owner_already_enrolled, google_owner_changed"},{"429","google_login_limit, session_limit"},{"503","google_login_not_configured, google_unavailable, google_login_unavailable"}}}};if(e[2]=="public")item["access"]="public";out.push_back(item);}return out;}
}
